/ {
	i2c_emul_ctlr: i2c@400 {
		compatible = "zephyr,i2c-emul-controller";
		label = "I2C_EMUL_0";
		reg = <0x400 0x100>;
		#address-cells = <1>;
		#size-cells = <0>;

		emul0: emul@20 {
			compatible = "zephyr,i2c-emul";
			reg = <0x20>;
			label = "EMUL_0";
		};
	};

	aliases {
		i2c-emul-ctlr-0 = &i2c_emul_ctlr;
	};
};
